<template>
  <main class="inquiry-workspace" :class="{'nav-open': navOpen, 'side-open': sideOpen}">
    <header class="workspace-toolbar">
      <div class="toolbar-brand"><button class="icon-control mobile-toggle" type="button" aria-label="打开空间导航" @click="navOpen = !navOpen">☰</button><span class="brand-icon">✳</span><div><span class="eyebrow">INQUIRY WORKSPACE</span><strong>{{ workspace?.title || '探究教学工作空间' }}</strong></div></div>
      <nav v-if="workspace" aria-label="工作空间工具栏" class="view-tabs"><button type="button" :disabled="openingSpace" :class="{active:view==='canvas'}" @click="switchView('canvas')">教学设计</button><button type="button" :class="{active:view==='experiment'}" :disabled="openingSpace" @click="switchView('experiment')">实验探索</button><button type="button" :class="{active:view==='report'}" :disabled="openingSpace" @click="switchView('report')">报告预览</button><button type="button" :class="{active:view==='graph'}" :disabled="openingSpace" @click="selectGraph()">Agent 编排图</button></nav>
      <nav v-else aria-label="工作空间工具栏" class="toolbar-placeholder">从一个问题，开始探究</nav>
      <div class="toolbar-actions"><span v-if="workspace" class="save-indicator" role="status"><i/>{{ saveLabel }}</span><button v-if="workspace && view==='report'" type="button" class="toolbar-secondary" :disabled="busy || !reportRef" @click="reportRef?.makeSnapshot()">固定快照</button><button v-if="workspace && view==='report'" type="button" class="toolbar-secondary" :disabled="busy || !reportRef?.snapshotId" @click="reportRef?.download()">下载 Word</button><button v-if="workspace" type="button" class="toolbar-secondary" :disabled="!inspected" @click="showVersions">对象版本</button><button v-if="workspace" type="button" class="toolbar-secondary" :disabled="busy || isRunning" @click="openGenerate">追加教学对象</button><button v-if="workspace && view!=='report'" type="button" class="toolbar-secondary" @click="switchView('report')">报告导出</button><button v-if="admin" type="button" class="toolbar-secondary" @click="openSettings">课标设置</button><button type="button" class="toolbar-exit" @click="closeWorkspace">返回对话模式</button><button v-if="workspace" type="button" class="icon-control mobile-toggle" aria-label="打开协作面板" @click="sideOpen = !sideOpen">✳</button></div>
    </header>

    <div v-if="error" class="workspace-alert" role="alert">{{ error }}<button type="button" aria-label="关闭提示" @click="error = ''">×</button></div>
    <div v-if="showSettings" class="workspace-modal-backdrop" @click.self="showSettings = false"><section class="workspace-modal" role="dialog" aria-modal="true" aria-labelledby="settings-heading"><div class="modal-heading"><div><span class="eyebrow">CURRICULUM ACCESS</span><h2 id="settings-heading">课标检索设置</h2></div><button type="button" aria-label="关闭设置" @click="showSettings = false">×</button></div><p>每次检索只使用所选教师专家当前获授权的文件。</p><label v-for="expert in experts" :key="expert.id" class="settings-option"><input v-model="allowedExperts" type="checkbox" :value="expert.id"> {{ expert.name }}</label><div class="modal-actions"><button type="button" @click="showSettings = false">取消</button><button type="button" class="primary" :disabled="busy" @click="saveSettings">保存设置</button></div></section></div>

    <section v-if="accessRestricted" class="restricted-view" role="alert"><h2>工作空间暂不可访问</h2><p>课程依据或访问权限可能已变更。请重新检查权限或联系管理员。</p><button type="button" @click="retryAccess">重新检查</button><button type="button" @click="backToList">返回空间列表</button></section>
    <div v-show="!accessRestricted" class="workspace-layout" :class="{'nav-collapsed':navCollapsed,'side-collapsed':sideCollapsed}">
      <aside class="workspace-nav" aria-label="空间导航"><div class="nav-head"><span>工作空间</span><button type="button" :aria-label="navCollapsed ? '展开导航' : '收起导航'" @click="navCollapsed = !navCollapsed">{{ navCollapsed ? '›' : '‹' }}</button></div><div v-show="!navCollapsed" class="nav-content"><button type="button" class="new-space-button" @click="backToList">＋ 新建教学空间</button><div v-if="workspace" class="nav-label">WORKSPACE</div><template v-if="workspace"><button type="button" class="directory-link workspace-view-link" :class="{active:view==='graph'}" @click="selectGraph(); navOpen=false">◇ <span>Agent 编排</span></button><button type="button" class="directory-link workspace-view-link" :class="{active:view==='canvas'}" @click="switchView('canvas'); navOpen=false">▦ <span>教学画布</span></button><button type="button" class="directory-link workspace-view-link" :class="{active:view==='report'}" @click="switchView('report'); navOpen=false">▤ <span>教学报告</span></button></template><div class="nav-label">最近工作空间</div><p v-if="loadingSpaces" class="nav-muted">正在加载…</p><p v-else-if="!spaces.length" class="nav-muted">还没有空间</p><button v-for="item in spaces" :key="item.id" type="button" class="space-link" :class="{active: workspace?.id===item.id}" @click="open(item.id)"><span>◇</span><span>{{ item.title }}</span></button>
        <template v-if="workspace"><div class="nav-label nav-separator">教学目录</div><button v-for="group in navigationGroups" :key="group.key" type="button" class="directory-link" @click="jumpGroup(group.key)"><span>{{ group.label }}</span><small>{{ group.count }}</small></button><div class="nav-label nav-separator">工作记录</div><button type="button" class="directory-link" :disabled="!inspected" @click="showVersions">对象版本 <span>›</span></button><button type="button" class="directory-link" :disabled="!run" @click="openDetails">最近执行 <span>›</span></button></template><button v-if="admin" type="button" class="directory-link nav-separator" @click="openSettings">课标检索设置 <span>›</span></button></div></aside>

      <section class="workspace-main" ref="mainScroll">
        <div v-if="!workspace" class="workspace-home"><div class="home-hero"><span class="eyebrow">CREATE SOMETHING MEANINGFUL</span><h1>从一个好问题开始，<br>设计有生命力的探究。</h1><p>将你的教学想法变成可编辑、可实验的教学空间。</p><label for="workspace-title">教学需求</label><textarea id="workspace-title" v-model="title" rows="4" placeholder="描述教学主题、学生年级和课堂目标"/><TeachingContextEditor v-model="teachingContext"/><div class="home-actions"><label for="workspace-mode">生成范围 <select id="workspace-mode" v-model="mode"><option value="lesson">完整教学设计</option><option value="experiment">独立实验设计</option></select></label><button type="button" class="primary" :disabled="busy || !title.trim()" @click="create">{{ busy ? '正在创建…' : '生成教学空间 →' }}</button></div><p class="home-note">✦ 生成依据会遵循当前已授权的资料</p></div><div class="home-recent"><div class="group-heading"><div><h2>最近的教学空间</h2></div></div><p v-if="!spaces.length" class="nav-muted">你的空间会显示在这里。</p><button v-for="item in spaces" :key="item.id" type="button" class="recent-card" @click="open(item.id)"><span class="recent-icon">◇</span><span><strong>{{ item.title }}</strong><small>打开教学空间 →</small></span></button></div></div>
        <template v-else>
          <div v-if="view !== 'graph' && run && (isRunning || run.status === 'waiting_review' || run.status === 'failed')" class="run-banner"><span class="run-dot"/><div><strong>{{ runLabel(run.status) }}</strong><span v-if="run.error"> · {{ run.error }}</span></div><button type="button" @click="openDetails">执行详情</button></div>
          <TeachingCanvas v-show="view==='canvas'" ref="canvasRef" :title="workspace.title" :artifacts="teachingArtifacts" :dependencies="dependencies" :selected-id="inspectedId" :selected-ids="selectedIds" :busy="busy || isRunning" @inspect="inspectArtifact" @experiment="openExperiment" @move="moveArtifact" @toggle-multi="toggleMulti" @save-title="saveTitle" @add-experiment="addExperiment"/>
          <div v-show="view==='experiment'" class="embedded-view"><ReflectionExperiment v-if="selectedExperiment" ref="experimentRef" :key="selectedExperiment.id" :workspace-id="workspace.id" :experiment="selectedExperiment" :record="currentRecord" @back="switchView('canvas')" @updated="updateRecord" @refreshed="applyWorkspace"/><div v-else class="canvas-empty"><h2>实验探索</h2><p>从教学画布选择支持交互的实验；没有对应组件的活动仍可在画布中查看和编辑。</p><details><summary>可选专业交互组件</summary><button type="button" class="primary" :disabled="busy || isRunning" @click="addExperiment">添加光的反射实验</button></details></div></div>
          <div v-show="view==='graph'" class="embedded-view dag-embedded"><TaskComposer :title="workspace.title" v-model:mode="mode" v-model:context="teachingContext" :baseline-context="workspace.latest_run?.teaching_context || {}" :busy="busy || isRunning" @submit="submitComposer"/><AgentDagView v-if="graphOpened" :key="workspace.id" :workspace-id="workspace.id" :latest-run-id="run?.id || ''" :active="view==='graph' && !accessRestricted" @interaction="autoAdvanceRun=''"/></div>
          <div v-show="view==='report'" class="embedded-view"><ReportPreview :key="workspace.id" ref="reportRef" :workspace-id="workspace.id" :artifacts="workspace.artifacts" @back="switchView('canvas')" @updated="updateRecord" @refreshed="applyWorkspace" @locate="locateReportArtifact"/></div>
        </template>
      </section>

      <aside v-if="workspace" class="workspace-side" aria-label="教学协作面板"><div class="side-tabs"><button type="button" :class="{active:sideTab==='copilot'}" @click="sideTab='copilot'; sideCollapsed=false">AI 协作</button><button type="button" :class="{active:sideTab==='inspector'}" @click="sideTab='inspector'; sideCollapsed=false">对象属性</button><button type="button" class="collapse-side" :aria-label="sideCollapsed ? '展开协作面板' : '收起协作面板'" @click="sideCollapsed=!sideCollapsed">{{ sideCollapsed ? '‹' : '›' }}</button></div><div v-show="!sideCollapsed" class="side-scroll"><CopilotPanel v-show="sideTab==='copilot'" :title="workspace.title" :artifact="inspected" :artifacts="teachingArtifacts" :selected-ids="selectedIds" :busy="busy || isRunning" :dirty="inspectorDirty" :running="isRunning" :run="run" :preview="impact" @generate="startRun" @preview="previewImpact" @replan="startReplan" @cancel="cancelRun" @approve="approveRun" @details="openDetails"/><ArtifactInspector v-show="sideTab==='inspector'" :artifact="inspected" :draft="draft" :artifacts="teachingArtifacts" :busy="busy || isRunning" :dirty="inspectorDirty" :conflict="inspectorConflict" :latest="latestArtifact" @change="changeDraft" @save="saveArtifact" @discard="discardDraft" @lock="toggleLock" @versions="showVersions" @merge-latest="mergeLatest"/></div></aside>
    </div>
    <div v-if="showDetails" class="workspace-modal-backdrop" @click.self="showDetails=false"><section class="workspace-modal" role="dialog" aria-modal="true" aria-labelledby="run-details-heading"><div class="modal-heading"><div><span class="eyebrow">RUN DETAILS</span><h2 id="run-details-heading">最近执行详情</h2></div><button type="button" aria-label="关闭执行详情" @click="showDetails=false">×</button></div><template v-if="run"><p>{{ runLabel(run.status) }}</p><p v-if="run.error" role="alert">{{ run.error }}</p><ul class="run-list"><li v-for="node in run.nodes" :key="node.id"><span>{{ node.capability }}</span><small>{{ runLabel(node.status) }} · 尝试 {{ node.attempts || 0 }} 次</small></li></ul><button v-if="isRunning || run.status==='waiting_review'" type="button" @click="cancelRun">取消本次运行</button><button v-if="run.review_approvable" type="button" @click="approveRun">已检查风险，确认继续</button></template><p v-else>暂无执行记录。</p></section></div>
    <div v-if="versionsOpen" class="workspace-modal-backdrop" @click.self="versionsOpen=false"><section class="workspace-modal" role="dialog" aria-modal="true" aria-labelledby="versions-heading"><div class="modal-heading"><div><span class="eyebrow">OBJECT HISTORY</span><h2 id="versions-heading">对象版本</h2></div><button type="button" aria-label="关闭版本" @click="versionsOpen=false">×</button></div><p>{{ inspected?.content.title || '当前对象' }} · 恢复会创建新版本</p><div v-for="version in versions" :key="version.version" class="version-row"><div><strong>版本 {{ version.version }}</strong><small>{{ version.created_at }} · {{ version.author_kind }}</small></div><button type="button" :disabled="busy || version.version===inspected?.version" @click="restoreVersion(version.version)">恢复</button><details><summary>查看内容</summary><pre>{{ JSON.stringify(version.content, null, 2) }}</pre></details></div></section></div>
  </main>
</template>

<script setup lang="ts">
import { computed, defineAsyncComponent, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue';
import ReflectionExperiment from './artifacts/ReflectionExperiment.vue';
const AgentDagView = defineAsyncComponent(() => import('./components/AgentDagView.vue'));
import ReportPreview from './components/ReportPreview.vue';
import TeachingCanvas from './components/TeachingCanvas.vue';
import TaskComposer from './components/TaskComposer.vue';
import TeachingContextEditor from './components/TeachingContextEditor.vue';
import { cleanTeachingContext } from './teachingContext';
import { getActivityComponent } from './activityComponents';
import ArtifactInspector from './components/ArtifactInspector.vue';
import CopilotPanel from './components/CopilotPanel.vue';
import { mergeArtifactDraft } from './components/artifactMerge';
import { getExperts } from '@/api';
import type { ExpertAgentItem } from '@/types';
import { jsonRequest, workspaceRequest, WorkspaceRequestError, type Artifact, type Dependency, type Workspace, type TeachingContextInput } from './api';
import './workspace.css';

type Run = {id:string;status:string;error:string;mode:string;teaching_context?:TeachingContextInput;review_approvable?:boolean;warnings:string[];nodes:Array<{id:string;capability:string;status:string;attempts?:number}>};
type Preview = {revision:number;fingerprint:string;targets:Array<{id:string;version:number;type:string}>;requires_review:string[]};
type Version = {version:number;content:Record<string,unknown>;created_at:string;author_kind:string};
const emit = defineEmits<{close:[]}>();
defineProps<{admin:boolean}>();
const workspace=ref<Workspace|null>(null), spaces=ref<Array<{id:string;title:string}>>([]), title=ref(''), mode=ref<'lesson'|'experiment'>('lesson');
const busy=ref(false), openingSpace=ref(false), loadingSpaces=ref(false), error=ref(''), view=ref<'canvas'|'experiment'|'report'|'graph'>('canvas');
const graphOpened=ref(false), autoAdvanceRun=ref('');
const teachingContext=ref<TeachingContextInput>({});
const run=ref<Run|null>(null), dependencies=ref<Dependency[]>([]), impact=ref<Preview|null>(null);
const navCollapsed=ref(false), sideCollapsed=ref(false), navOpen=ref(false), sideOpen=ref(false), sideTab=ref<'copilot'|'inspector'>('copilot');
const accessRestricted=ref(false);
const inspectedId=ref(''), experimentId=ref(''), selectedIds=ref<string[]>([]), showDetails=ref(false), showSettings=ref(false), versionsOpen=ref(false);
const experts=ref<ExpertAgentItem[]>([]), allowedExperts=ref<string[]>([]), versions=ref<Version[]>([]);
const drafts=reactive<Record<string,Record<string,any>>>({}), baselines=reactive<Record<string,string>>({});
const draftVersions=reactive<Record<string,number>>({});
const inspectorConflict=ref(false), latestArtifact=ref<Artifact|null>(null);
const canvasRef=ref<{isDirty:()=>boolean}|null>(null), experimentRef=ref<{isDirty:()=>boolean}|null>(null), reportRef=ref<{isDirty:()=>boolean;load:()=>Promise<void>;makeSnapshot:()=>Promise<void>;download:()=>Promise<void>;snapshotId:string}|null>(null), mainScroll=ref<HTMLElement|null>(null);
let pollTimer:ReturnType<typeof setTimeout>|undefined;
const isRunning=computed(()=>Boolean(run.value && ['queued','planning','running','evaluating'].includes(run.value.status)));
const teachingArtifacts=computed(()=>workspace.value?.artifacts.filter(a=>!['DataRecord','ReportNarrative'].includes(a.type)) || []);
const inspected=computed(()=>teachingArtifacts.value.find(a=>a.id===inspectedId.value) || null);
const selectedExperiment=computed(()=>teachingArtifacts.value.find(a=>a.id===experimentId.value && a.type==='Experiment' && getActivityComponent(a.content.component_type)?.renderer==='ReflectionExperiment') || null);
const currentRecord=computed(()=>workspace.value?.artifacts.find(a=>a.type==='DataRecord' && a.content.experiment_id===experimentId.value));
const draft=computed(()=>inspected.value ? drafts[inspected.value.id] || {} : {});
const inspectorDirty=computed(()=>!!inspected.value && !!drafts[inspected.value.id] && JSON.stringify(drafts[inspected.value.id])!==baselines[inspected.value.id]);
const anyDraftDirty=computed(()=>Object.keys(drafts).some(id=>JSON.stringify(drafts[id])!==baselines[id]));
const saveLabel=computed(()=>busy.value ? '正在保存' : anyDraftDirty.value || canvasRef.value?.isDirty() || experimentRef.value?.isDirty() || reportRef.value?.isDirty() ? '有未保存内容' : '已保存');
const navigationGroups=computed(()=>[{key:'goals',label:'学习目标',types:['LearningGoal']},{key:'questions',label:'探究问题',types:['InquiryQuestion']},{key:'knowledge',label:'知识依据',types:['KnowledgeCard']},{key:'activities',label:'实验与活动',types:['Experiment','InquiryActivity','ObservationTask','SurveyTask','ReadingInquiryTask','DataInquiryTask','CollaborationTask','EvidenceRecord','PresentationTask']},{key:'assessment',label:'学习评价',types:['Assessment']}].map(g=>({...g,count:teachingArtifacts.value.filter(a=>g.types.includes(a.type)).length})));
function clone(value:Record<string,any>) { return JSON.parse(JSON.stringify(value)) as Record<string,any>; }
function dirty() { return anyDraftDirty.value || !!canvasRef.value?.isDirty() || !!experimentRef.value?.isDirty() || !!reportRef.value?.isDirty(); }
function confirmLeave() { return !dirty() || window.confirm('当前内容尚未保存，确定离开吗？'); }
function beforeUnload(event:BeforeUnloadEvent) { if(dirty()){event.preventDefault();event.returnValue='';} }
function closeWorkspace(){if(confirmLeave()) emit('close');}
function failed(e:unknown){error.value=e instanceof Error?e.message:'操作失败';}
function runLabel(status:string){return ({queued:'等待执行',planning:'理解需求并规划',running:'正在生成',succeeded:'已完成',completed:'生成完成',failed:'生成失败',cancelled:'已停止',waiting_review:'需要教师审核'} as Record<string,string>)[status] || status;}
function syncDrafts(data:Workspace){for(const a of data.artifacts){const current=JSON.stringify(a.content);if(!drafts[a.id] || JSON.stringify(drafts[a.id])===baselines[a.id]){drafts[a.id]=clone(a.content);baselines[a.id]=current;draftVersions[a.id]=a.version;}}}
function applyWorkspace(data:Workspace){workspace.value=data;syncDrafts(data);if(!experimentId.value){experimentId.value=data.artifacts.find(a=>a.type==='Experiment' && getActivityComponent(a.content.component_type)?.renderer==='ReflectionExperiment')?.id || '';}}
async function refresh(){if(!workspace.value)return;const id=workspace.value.id;const [data, links]=await Promise.all([workspaceRequest<Workspace>(`/${id}`),workspaceRequest<Dependency[]>(`/${id}/dependencies`)]);if(workspace.value?.id!==id)return;applyWorkspace(data);dependencies.value=links;}
async function loadSpaces(){loadingSpaces.value=true;try{spaces.value=await workspaceRequest();}catch(e){failed(e);}finally{loadingSpaces.value=false;}}
async function open(id:string,resume=true,skipConfirm=false){if(workspace.value?.id!==id && !skipConfirm && !confirmLeave())return;openingSpace.value=true;error.value='';try{const [data,links]=await Promise.all([workspaceRequest<Workspace>(`/${id}`),workspaceRequest<Dependency[]>(`/${id}/dependencies`)]);if(workspace.value?.id!==id){Object.keys(drafts).forEach(key=>{delete drafts[key];delete baselines[key];});inspectedId.value='';experimentId.value='';selectedIds.value=[];impact.value=null;view.value='canvas';teachingContext.value=data.latest_run?.teaching_context || {};}applyWorkspace(data);dependencies.value=links;sessionStorage.setItem('inquiry-workspace-current',id);navOpen.value=false;if(resume){if(pollTimer)clearTimeout(pollTimer);run.value=data.latest_run || null;if(isRunning.value){autoAdvanceRun.value=run.value?.id || '';void switchView('graph');void pollRun();}}}catch(e){failed(e);}finally{openingSpace.value=false;}}
async function create(){const context={...teachingContext.value};busy.value=true;error.value='';try{const item=await workspaceRequest<{id:string}>('',jsonRequest('POST',{title:title.value.trim()}));await loadSpaces();await open(item.id);teachingContext.value=context;await startRun(title.value.trim());}catch(e){failed(e);}finally{busy.value=false;}}
function backToList(){if(!confirmLeave())return;if(pollTimer)clearTimeout(pollTimer);workspace.value=null;run.value=null;teachingContext.value={};inspectedId.value='';experimentId.value='';selectedIds.value=[];impact.value=null;accessRestricted.value=false;sessionStorage.removeItem('inquiry-workspace-current');Object.keys(drafts).forEach(k=>{delete drafts[k];delete baselines[k];delete draftVersions[k];});void loadSpaces();navOpen.value=false;}
function accessDenied(event:Event){const detail=(event as CustomEvent<{path:string}>).detail;if(workspace.value && (detail?.path === `/${workspace.value.id}` || detail?.path?.startsWith(`/${workspace.value.id}/`))){accessRestricted.value=true;showDetails.value=false;versionsOpen.value=false;}}
async function retryAccess(){try{await refresh();accessRestricted.value=false;error.value='';}catch(e){failed(e);}}
async function switchView(next:'canvas'|'experiment'|'report'|'graph'){if(next==='graph')graphOpened.value=true;view.value=next;if(next==='report'){await nextTick();try{await reportRef.value?.load();}catch(e){failed(e);}}}
function selectGraph(){autoAdvanceRun.value='';void switchView('graph');}
function locateReportArtifact(id:string){const item=teachingArtifacts.value.find(a=>a.id===id);if(!item)return;inspectArtifact(item);view.value='canvas';void nextTick(()=>document.getElementById(`artifact-${id}`)?.scrollIntoView({behavior:'smooth',block:'center'}));}
function jumpGroup(key:string){view.value='canvas';navOpen.value=false;void nextTick(()=>document.getElementById(`group-${key}`)?.scrollIntoView({behavior:'smooth',block:'start'}));}
function inspectArtifact(item:Artifact){inspectedId.value=item.id;impact.value=null;inspectorConflict.value=false;latestArtifact.value=null;sideTab.value='inspector';sideCollapsed.value=false;sideOpen.value=true;}
function openExperiment(id:string){if(experimentId.value && experimentId.value!==id && experimentRef.value?.isDirty() && !window.confirm('观察结论尚未保存，确定切换实验吗？'))return;experimentId.value=id;view.value='experiment';}
function toggleMulti(id:string){selectedIds.value=selectedIds.value.includes(id)?selectedIds.value.filter(item=>item!==id):[...selectedIds.value,id];impact.value=null;}
function changeDraft(key:string,value:unknown){if(inspected.value){drafts[inspected.value.id][key]=value;impact.value=null;}}
function discardDraft(){if(!inspected.value)return;const item=latestArtifact.value || inspected.value;drafts[item.id]=clone(item.content);baselines[item.id]=JSON.stringify(item.content);draftVersions[item.id]=item.version;updateRecord(item);inspectorConflict.value=false;latestArtifact.value=null;error.value='';}
function updateRecord(record:Artifact){if(!workspace.value)return;const index=workspace.value.artifacts.findIndex(a=>a.id===record.id);if(index<0)workspace.value.artifacts.push(record);else workspace.value.artifacts[index]=record;syncDrafts(workspace.value);}
async function saveContent(item:Artifact,content:Record<string,unknown>,expectedVersion:number){if(!workspace.value)return;busy.value=true;error.value='';const before=JSON.stringify(drafts[item.id]);const wasPristine=before===baselines[item.id];try{const updated=await workspaceRequest<Artifact>(`/${workspace.value.id}/artifacts/${item.id}`,jsonRequest('PATCH',{expected_version:expectedVersion,content}));if(JSON.stringify(drafts[item.id])===before && (wasPristine || before===JSON.stringify(content)))drafts[item.id]=clone(updated.content);baselines[item.id]=JSON.stringify(updated.content);draftVersions[item.id]=updated.version;updateRecord(updated);inspectorConflict.value=false;latestArtifact.value=null;await refresh();}catch(e){if(e instanceof WorkspaceRequestError && e.status===409){inspectorConflict.value=true;inspectedId.value=item.id;sideTab.value='inspector';sideCollapsed.value=false;try{const data=await workspaceRequest<Workspace>(`/${workspace.value.id}`);latestArtifact.value=data.artifacts.find(a=>a.id===item.id)||null;}catch{} }failed(e);}finally{busy.value=false;}}
async function saveArtifact(){if(inspected.value)await saveContent(inspected.value,clone(draft.value),draftVersions[inspected.value.id]);}
async function saveTitle(item:Artifact,value:string,baseVersion:number){if(drafts[item.id] && JSON.stringify(drafts[item.id])!==baselines[item.id]){error.value='请先保存或放弃该对象的属性草稿。';return;}await saveContent(item,{...item.content,title:value},baseVersion);}
function mergeLatest(){if(!latestArtifact.value || !workspace.value)return;const latest=latestArtifact.value;const merged=mergeArtifactDraft(JSON.parse(baselines[latest.id] || '{}'),drafts[latest.id] || {},latest.content);const index=workspace.value.artifacts.findIndex(a=>a.id===latest.id);if(index>=0)workspace.value.artifacts[index]=latest;drafts[latest.id]=merged.content;baselines[latest.id]=JSON.stringify(latest.content);draftVersions[latest.id]=latest.version;inspectorConflict.value=false;latestArtifact.value=null;error.value=merged.conflicts.length ? `以下字段同时被修改，已保留你的输入，请检查后保存：${merged.conflicts.join('、')}` : '已合并最新内容，请检查后保存。';}
async function toggleLock(){if(!workspace.value||!inspected.value)return;busy.value=true;try{const item=await workspaceRequest<Artifact>(`/${workspace.value.id}/artifacts/${inspected.value.id}/lock`,jsonRequest('PUT',{expected_version:inspected.value.version,locked:!inspected.value.locked}));updateRecord(item);await refresh();}catch(e){failed(e);}finally{busy.value=false;}}
async function showVersions(){if(!workspace.value||!inspected.value)return;try{versions.value=await workspaceRequest<Version[]>(`/${workspace.value.id}/artifacts/${inspected.value.id}/versions`);versionsOpen.value=true;}catch(e){failed(e);}}
async function restoreVersion(version:number){if(!workspace.value||!inspected.value||!confirmLeave())return;busy.value=true;try{const item=await workspaceRequest<Artifact>(`/${workspace.value.id}/artifacts/${inspected.value.id}/restore`,jsonRequest('POST',{expected_version:inspected.value.version,version}));drafts[item.id]=clone(item.content);baselines[item.id]=JSON.stringify(item.content);updateRecord(item);versionsOpen.value=false;await refresh();}catch(e){failed(e);}finally{busy.value=false;}}
async function moveArtifact(items:Artifact[],index:number,direction:number){if(!workspace.value)return;const ids=items.map(item=>item.id), target=index+direction;[ids[index],ids[target]]=[ids[target],ids[index]];busy.value=true;try{await workspaceRequest(`/${workspace.value.id}/artifacts/order`,jsonRequest('PUT',{expected_revision:workspace.value.revision,artifact_ids:ids}));await refresh();}catch(e){failed(e);}finally{busy.value=false;}}
async function addExperiment(){if(!workspace.value)return;busy.value=true;try{const item=await workspaceRequest<Artifact>(`/${workspace.value.id}/experiments/reflection`,{method:'POST'});updateRecord(item);if(!experimentId.value)experimentId.value=item.id;await refresh();}catch(e){failed(e);}finally{busy.value=false;}}
async function submitComposer(goal:string, scope:'new'|'append', inputContext:TeachingContextInput){if(scope==='append'){await startRun(goal);return;}if(!confirmLeave())return;const context=cleanTeachingContext(inputContext);busy.value=true;error.value='';try{const item=await workspaceRequest<{id:string}>('',jsonRequest('POST',{title:goal}));await loadSpaces();await open(item.id,true,true);if(workspace.value?.id!==item.id)return;teachingContext.value=context;await startRun(goal);}catch(e){failed(e);}finally{busy.value=false;}}
async function startRun(goal:string){if(!workspace.value||!goal.trim()||!confirmLeave())return;busy.value=true;error.value='';try{run.value=await workspaceRequest<Run>(`/${workspace.value.id}/runs`,jsonRequest('POST',{goal:goal.trim(),mode:mode.value,teaching_context:cleanTeachingContext(teachingContext.value),idempotency_key:crypto.randomUUID()}));sideTab.value='copilot';sideCollapsed.value=false;autoAdvanceRun.value=run.value.id;await switchView('graph');await pollRun();}catch(e){failed(e);}finally{busy.value=false;}}
function openGenerate(){sideTab.value='copilot';sideCollapsed.value=false;sideOpen.value=true;}
async function pollRun(){if(!workspace.value||!run.value)return;const workspaceId=workspace.value.id,runId=run.value.id;try{const current=await workspaceRequest<Run>(`/${workspaceId}/runs/${runId}`);if(workspace.value?.id!==workspaceId||run.value?.id!==runId)return;run.value=current;if(isRunning.value)pollTimer=setTimeout(pollRun,1500);else {await refresh();if(view.value==='report')await reportRef.value?.load();if(current.status==='completed' && view.value==='graph' && autoAdvanceRun.value===runId){autoAdvanceRun.value='';await switchView('canvas');}}}catch(e){failed(e);if(workspace.value?.id===workspaceId && run.value?.id===runId && isRunning.value)pollTimer=setTimeout(pollRun,3000);}}
async function cancelRun(){if(!workspace.value||!run.value)return;try{run.value=await workspaceRequest<Run>(`/${workspace.value.id}/runs/${run.value.id}/cancel`,{method:'POST'});}catch(e){failed(e);}}
async function approveRun(){if(!workspace.value||!run.value)return;try{run.value=await workspaceRequest<Run>(`/${workspace.value.id}/runs/${run.value.id}/resume`,jsonRequest('POST',{decision:'approve'}));await refresh();}catch(e){failed(e);}}
function openDetails(){showDetails.value=true;}
async function previewImpact(){if(!workspace.value||!inspected.value||inspectorDirty.value)return;error.value='';try{impact.value=await workspaceRequest<Preview>(`/${workspace.value.id}/artifacts/${inspected.value.id}/replan-preview?expected_version=${inspected.value.version}`);}catch(e){impact.value=null;failed(e);}}
async function startReplan(instruction:string){if(!workspace.value||!inspected.value||!impact.value?.targets.length)return;busy.value=true;error.value='';try{run.value=await workspaceRequest<Run>(`/${workspace.value.id}/artifacts/${inspected.value.id}/replan`,jsonRequest('POST',{expected_version:inspected.value.version,expected_revision:impact.value.revision,preview_fingerprint:impact.value.fingerprint,instruction,idempotency_key:crypto.randomUUID()}));impact.value=null;autoAdvanceRun.value=run.value.id;await switchView('graph');await pollRun();}catch(e){impact.value=null;failed(e);}finally{busy.value=false;}}
async function openSettings(){busy.value=true;try{const [available,settings]=await Promise.all([getExperts('teacher'),workspaceRequest<{expert_ids:string[]}>('/admin/settings')]);experts.value=available;allowedExperts.value=settings.expert_ids;showSettings.value=true;}catch(e){failed(e);}finally{busy.value=false;}}
async function saveSettings(){busy.value=true;try{await workspaceRequest('/admin/settings',jsonRequest('PUT',{expert_ids:allowedExperts.value}));showSettings.value=false;}catch(e){failed(e);}finally{busy.value=false;}}
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);window.addEventListener('inquiry-workspace:access-denied',accessDenied);await loadSpaces();const id=sessionStorage.getItem('inquiry-workspace-current');if(id)await open(id);});
onBeforeUnmount(()=>{window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('inquiry-workspace:access-denied',accessDenied);if(pollTimer)clearTimeout(pollTimer);});
</script>
